<template>
  <section class="workspace-view">
    <div class="workbench-head"><div><h2>{{ tx.title }}</h2><p>{{ tx.subtitle }}</p></div><div class="filters"><input v-model="workshopId" :aria-label="tx.workshop" /><input v-model="productionDate" type="date" :aria-label="tx.date" /><button :disabled="loading" @click="load">↻ {{ tx.refresh }}</button></div></div>

    <template v-if="left && right">
      <div class="version-selectors">
        <label class="panel"><span>{{ tx.baseline }}</span><select v-model="leftId"><option v-for="item in versions" :key="item.version_id" :value="item.version_id">{{ versionLabel(item) }}</option></select><small>{{ formatDateTime(locale,left.updated_at) }} · {{ statusText(locale,left.status) }}</small></label>
        <div class="compare-mark"><i></i><b>⇄</b><i></i></div>
        <label class="panel"><span>{{ tx.candidate }}</span><select v-model="rightId"><option v-for="item in versions" :key="item.version_id" :value="item.version_id">{{ versionLabel(item) }}</option></select><small>{{ formatDateTime(locale,right.updated_at) }} · {{ statusText(locale,right.status) }}</small></label>
      </div>

      <article class="panel decision-panel">
        <div class="decision-title"><div><h3>{{ tx.decision }}</h3><p>{{ tx.decisionHint }}</p></div><span :class="['verdict',verdict.tone]">{{ verdict.text }}</span></div>
        <div class="metric-grid">
          <div class="metric-head"><span>{{ tx.metric }}</span><b>{{ tx.baseline }}</b><i>{{ tx.delta }}</i><b>{{ tx.candidate }}</b></div>
          <div class="metric-row" v-for="metric in metrics" :key="metric.key"><span>{{ metric.label }}</span><b>{{ metricValue(left,metric.key) }}</b><i :class="deltaClass(metric.key)">{{ deltaValue(metric.key) }}</i><b>{{ metricValue(right,metric.key) }}</b></div>
        </div>
      </article>

      <div class="compare-layout">
        <article class="panel plan-side"><div class="plan-head"><div><span>{{ tx.baseline }}</span><h3>{{ left.plan.title }}</h3><small class="mono">{{ left.plan.plan_id }}</small></div><b>V{{ left.revision }}</b></div><assignment-list :version="left" :locale="locale" /></article>
        <article class="panel plan-side candidate"><div class="plan-head"><div><span>{{ tx.candidate }}</span><h3>{{ right.plan.title }}</h3><small class="mono">{{ right.plan.plan_id }}</small></div><b>V{{ right.revision }}</b></div><assignment-list :version="right" :locale="locale" /></article>
      </div>

      <div class="action-bar panel"><div><span>{{ tx.releasePolicy }}</span><small>{{ tx.releaseHint }}</small></div><button :disabled="right.status!=='need_review'" @click="$emit('open-review',right.task_id)">{{ right.status==='need_review'?tx.openReview:tx.notPending }} →</button></div>
    </template>
    <div v-else-if="!loading" class="panel empty"><b>◇</b><span>{{ tx.empty }}</span><small>{{ tx.emptyHint }}</small></div>
    <p v-if="error" class="error-line">{{ error }}</p>
  </section>
</template>

<script setup lang="ts">
import { computed,defineComponent,h,onMounted,ref,type PropType } from 'vue'
import { getPlanVersions } from '../services/api'
import type { PlanVersion } from '../types'
import { formatDateTime,formatNumber,statusText,type Locale } from '../utils/workbench'
const props=defineProps<{locale:Locale}>()
defineEmits<{(event:'open-review',taskId:string):void}>()
type MetricKey='planned_quantity'|'on_time_rate'|'average_utilization'|'overtime_minutes'|'changeover_count'|'risk_count'
const processLabel=(locale:Locale,value:string)=>locale==='en-US'?(value==='组装'?'Assembly':value==='测试'?'Test':'Packaging'):locale==='zh-TW'?value.replace('组','組').replace('测试','測試').replace('包装','包裝'):value
const AssignmentList=defineComponent({
  props:{version:{type:Object as PropType<PlanVersion>,required:true},locale:{type:String as PropType<Locale>,required:true}},
  setup(childProps){return()=>h('div',{class:'assignment-list'},childProps.version.plan.assignments.slice(0,6).map(item=>h('div',{class:'assignment-item'},[h('span',{class:'mono'},item.order_id),h('b',`${processLabel(childProps.locale,item.process)} · ${item.station_code}`),h('small',`${childProps.locale==='en-US'?(item.team_name==='甲班'?'Team A':item.team_name==='乙班'?'Team B':item.team_name):item.team_name} · ${new Date(item.start_at).toLocaleTimeString(childProps.locale,{hour:'2-digit',minute:'2-digit',hour12:false})}–${new Date(item.end_at).toLocaleTimeString(childProps.locale,{hour:'2-digit',minute:'2-digit',hour12:false})}`)])))}
})
const versions=ref<PlanVersion[]>([]),leftId=ref(''),rightId=ref(''),loading=ref(false),error=ref(''),workshopId=ref('DIP-A'),productionDate=ref('2026-09-10')
const copy={
  'zh-TW':{title:'計畫版本比較',subtitle:'比較交期、負載、加班、換線與風險後，選定候選版本進入人工審核。',workshop:'車間代碼',date:'生產日期',refresh:'更新版本',baseline:'基準版本',candidate:'候選版本',decision:'方案差異判讀',decisionHint:'指標只支援決策；硬約束校驗與人工核准仍是下發前置條件。',metric:'比較指標',delta:'差異',quantity:'計畫數量',onTime:'準時達成率',load:'平均負載',overtime:'預估加班',changeover:'換線次數',risks:'風險數量',minutes:'分鐘',times:'次',items:'項',candidateBetter:'候選方案整體較優',baselineBetter:'基準方案整體較優',equivalent:'兩個方案關鍵指標相當',releasePolicy:'下發控制',releaseHint:'只有待審核版本可進入審核中心；核准後才允許送往 MES。',openReview:'將候選版本送至審核',notPending:'此版本不在待審狀態',empty:'目前沒有可比較的計畫版本',emptyHint:'先建立至少一個車間計畫；多次編排或人工修改後可查看版本差異。'},
  'zh-CN':{title:'计划版本对比',subtitle:'比较交期、负载、加班、换线与风险后，选择候选版本进入人工审核。',workshop:'车间编码',date:'生产日期',refresh:'更新版本',baseline:'基准版本',candidate:'候选版本',decision:'方案差异判断',decisionHint:'指标只辅助决策；硬约束校验和人工批准仍是下发前置条件。',metric:'对比指标',delta:'差异',quantity:'计划数量',onTime:'准时达成率',load:'平均负载',overtime:'预计加班',changeover:'换线次数',risks:'风险数量',minutes:'分钟',times:'次',items:'项',candidateBetter:'候选方案整体更优',baselineBetter:'基准方案整体更优',equivalent:'两个方案关键指标相当',releasePolicy:'下发控制',releaseHint:'只有待审核版本可进入审核中心；批准后才允许发送到 MES。',openReview:'将候选版本送至审核',notPending:'该版本不在待审状态',empty:'当前没有可对比的计划版本',emptyHint:'先创建至少一个车间计划；多次排产或人工修改后可查看版本差异。'},
  'en-US':{title:'Plan version comparison',subtitle:'Compare delivery, load, overtime, changeovers and risk before sending a candidate to review.',workshop:'Workshop code',date:'Production date',refresh:'Refresh versions',baseline:'Baseline',candidate:'Candidate',decision:'Difference assessment',decisionHint:'Metrics support the decision; constraint validation and human approval remain mandatory.',metric:'Metric',delta:'Delta',quantity:'Planned quantity',onTime:'On-time rate',load:'Average load',overtime:'Estimated overtime',changeover:'Changeovers',risks:'Risks',minutes:'min',times:'times',items:'items',candidateBetter:'Candidate is stronger overall',baselineBetter:'Baseline is stronger overall',equivalent:'Key metrics are equivalent',releasePolicy:'Release control',releaseHint:'Only pending candidates can enter review. MES release requires approval.',openReview:'Send candidate to review',notPending:'Version is not pending review',empty:'No comparable plan versions',emptyHint:'Create a workshop plan first. Further runs or human edits will produce comparison history.'},
}
const tx=computed(()=>copy[props.locale]),left=computed(()=>versions.value.find(v=>v.version_id===leftId.value)||null),right=computed(()=>versions.value.find(v=>v.version_id===rightId.value)||null)
const metrics=computed<Array<{key:MetricKey;label:string}>>(()=>[{key:'planned_quantity',label:tx.value.quantity},{key:'on_time_rate',label:tx.value.onTime},{key:'average_utilization',label:tx.value.load},{key:'overtime_minutes',label:tx.value.overtime},{key:'changeover_count',label:tx.value.changeover},{key:'risk_count',label:tx.value.risks}])
function versionLabel(v:PlanVersion){return `${v.task_name} · V${v.revision} · ${v.task_id.slice(-8)}`}
function raw(v:PlanVersion,key:MetricKey){return v.metrics[key]}
function metricValue(v:PlanVersion,key:MetricKey){const value=raw(v,key);if(key==='planned_quantity')return formatNumber(props.locale,value);if(key==='on_time_rate'||key==='average_utilization')return `${Math.round(value*100)}%`;if(key==='overtime_minutes')return `${value} ${tx.value.minutes}`;if(key==='changeover_count')return `${value} ${tx.value.times}`;return `${value} ${tx.value.items}`}
function delta(key:MetricKey){return right.value&&left.value?raw(right.value,key)-raw(left.value,key):0}
function deltaValue(key:MetricKey){const value=delta(key);if(!value)return '—';const sign=value>0?'+':'';if(key==='on_time_rate'||key==='average_utilization')return `${sign}${Math.round(value*100)}%`;return `${sign}${Math.round(value)}`}
function deltaClass(key:MetricKey){const value=delta(key);if(!value)return 'neutral';const lowerIsBetter=['overtime_minutes','changeover_count','risk_count'].includes(key);return (lowerIsBetter?value<0:value>0)?'better':'worse'}
const verdict=computed(()=>{if(!left.value||!right.value)return{text:'',tone:'neutral'};const score=(delta('on_time_rate')*100)-delta('overtime_minutes')/30-delta('changeover_count')*2-delta('risk_count')*2;return score>0.5?{text:tx.value.candidateBetter,tone:'better'}:score<-.5?{text:tx.value.baselineBetter,tone:'worse'}:{text:tx.value.equivalent,tone:'neutral'}})
async function load(){loading.value=true;error.value='';try{versions.value=await getPlanVersions({workshopId:workshopId.value,productionDate:productionDate.value});rightId.value=versions.value[0]?.version_id||'';leftId.value=versions.value[1]?.version_id||rightId.value}catch(e:any){error.value=e.message}finally{loading.value=false}}
onMounted(load)
</script>

<style scoped>
.workspace-view{display:grid;gap:16px}.workbench-head{display:flex;justify-content:space-between;align-items:end;gap:16px}.workbench-head h2{font:600 25px "Bahnschrift";margin:0}.workbench-head p{font-size:11px;color:var(--muted);margin:6px 0 0}.filters{display:flex;gap:7px}.filters input,.filters button,.version-selectors select{background:#111a1e;color:var(--paper);border:1px solid var(--steel);padding:9px 10px;font-size:9px}.version-selectors{display:grid;grid-template-columns:1fr 74px 1fr;gap:0;align-items:stretch}.version-selectors label{padding:14px 16px;display:grid;grid-template-columns:100px 1fr;gap:7px 12px;align-items:center}.version-selectors label>span{font-size:9px;color:var(--muted)}.version-selectors label>small{grid-column:2;font-size:8px;color:#607177}.compare-mark{display:flex;align-items:center}.compare-mark i{height:1px;background:var(--steel);flex:1}.compare-mark b{display:grid;place-items:center;width:30px;height:30px;border:1px solid var(--coolant);color:var(--coolant);font-size:13px}.decision-panel{padding:18px;clip-path:polygon(0 0,calc(100% - 14px) 0,100% 14px,100% 100%,0 100%)}.decision-title{display:flex;justify-content:space-between;border-bottom:1px solid var(--steel);padding-bottom:13px}.decision-title h3{font-size:14px;margin:0}.decision-title p{font-size:9px;color:var(--muted);margin:5px 0 0}.verdict{align-self:start;padding:6px 9px;border:1px solid var(--steel);font-size:9px}.verdict.better{color:var(--ok);border-color:rgba(117,198,154,.35)}.verdict.worse{color:var(--safety);border-color:rgba(245,166,35,.35)}.metric-grid{margin-top:10px}.metric-head,.metric-row{display:grid;grid-template-columns:1.5fr 1fr .65fr 1fr;gap:12px;align-items:center;padding:8px 10px}.metric-head{font-size:8px;color:#627277}.metric-head b:last-child,.metric-row b:last-child{text-align:right}.metric-head i,.metric-row i{text-align:center;font-style:normal}.metric-row{border-top:1px solid rgba(38,52,58,.65);font-size:10px}.metric-row span{color:var(--muted)}.metric-row i{font:9px "Cascadia Mono"}.metric-row i.better{color:var(--ok)}.metric-row i.worse{color:var(--oxide)}.metric-row i.neutral{color:#607177}.compare-layout{display:grid;grid-template-columns:1fr 1fr;gap:16px}.plan-side{padding:18px}.plan-side.candidate{box-shadow:inset 2px 0 var(--coolant)}.plan-head{display:flex;justify-content:space-between;border-bottom:1px solid var(--steel);padding-bottom:13px}.plan-head span,.plan-head h3,.plan-head small{display:block}.plan-head span{font-size:8px;color:var(--muted)}.plan-head h3{font-size:13px;margin:4px 0}.plan-head small{font-size:8px;color:#607177}.plan-head>b{font:600 18px "Bahnschrift";color:var(--coolant)}:deep(.assignment-list){display:grid;margin-top:9px}:deep(.assignment-item){display:grid;grid-template-columns:1fr 1.25fr 1fr;gap:10px;padding:8px;border-bottom:1px solid rgba(38,52,58,.62);align-items:center}:deep(.assignment-item span){font-size:8px;color:#738489}:deep(.assignment-item b){font-size:9px}:deep(.assignment-item small){font-size:8px;color:var(--muted);text-align:right}.action-bar{display:flex;justify-content:space-between;align-items:center;padding:13px 16px;border-left:2px solid var(--safety)}.action-bar span,.action-bar small{display:block}.action-bar span{font-size:10px}.action-bar small{font-size:8px;color:var(--muted);margin-top:4px}.action-bar button{padding:10px 14px;border:0;background:var(--coolant);color:#071115;font-weight:700;font-size:10px}.action-bar button:disabled{background:#27363b;color:#68777b}.empty{padding:90px;display:grid;place-items:center;gap:8px;color:#68777b}.empty b{font-size:24px;color:var(--coolant)}.empty span{font-size:11px}.empty small{font-size:9px}.error-line{color:#ef896e;font-size:10px}.mono{font-family:"Cascadia Mono",Consolas,monospace}@media(max-width:950px){.compare-layout{grid-template-columns:1fr}.version-selectors{grid-template-columns:1fr}.compare-mark{height:35px;justify-content:center}.compare-mark i{max-width:40px}.filters input{width:100px}}@media(max-width:650px){.workbench-head{display:block}.filters{margin-top:12px}.version-selectors label{grid-template-columns:1fr}.version-selectors label>small{grid-column:auto}.metric-head,.metric-row{grid-template-columns:1.2fr .8fr .6fr .8fr}:deep(.assignment-item){grid-template-columns:1fr}.action-bar{display:block}.action-bar button{width:100%;margin-top:10px}}
</style>
